package com.example.corejava.capstone;
import com.example.corejava.domain.*; import com.example.corejava.service.AnalyticsService; import java.math.BigDecimal; import java.time.Instant; import java.util.*;
public final class CapstoneDemo { public static void main(String[] args)throws Exception { Product product=new Product(1L,"Keyboard",new BigDecimal("75.00"),10); InventoryManager inventory=new InventoryManager();inventory.add(product);try(OrderProcessor processor=new OrderProcessor(inventory,2)){for(long i=1;i<=5;i++)processor.submit(new Order(i,101L,List.of(new OrderItem(product,1)),OrderStatus.PENDING,Instant.now()));Thread.sleep(250);for(long i=1;i<=5;i++)System.out.println("Order "+i+": "+processor.get(i).status());System.out.println("Remaining stock: "+inventory.remaining(product.id()));}}}
